          );
          const json = await res.json();
          if (!json?.imageData) return;
          map[item.id] = `data:image/jpeg;base64,${json.imageData}`;
        } catch (err) {
          if (err?.name === "AbortError") return;
          console.error("Image fetch failed:", err);
        }
      })
    );

    if (!controller.signal.aborted) {
      setImageUrls(map);
    }
  }
