  </thead>
  <tbody>
    {items.map((item, idx) => (
      <tr key={idx}>
        <td>{item.serial}</td>
        <td>{item.name}</td>
        <td>
          {imageUrls[item.id] ? (
            <img
              src={imageUrls[item.id]}
              alt={item.name}
              onClick={() => handleImageClick(imageUrls[item.id], item)}
              style={{
                width: "50px",
                height: "50px",
                objectFit: "contain",
                borderRadius: "6px",
                border: "1px solid red",
              }}
            />
          ) : (
            <span className="text-muted small">Loading</span>
          )}
        </td>
        <td>{item.code}</td>
        <td>{item.category}</td>
        <td>₹{item.mrp}</td>
        <td>{item.discount}%</td>
        <td>₹{item.afterDiscountPrice.toFixed(0)}</td>
        <td>{item.quantity}</td>
        <td>₹{item.total.toFixed(0)}</td>
      </tr>
    ))}
  </tbody>
  <tfoot>
     <tr>
  <td colSpan="5" className="text-end fw-bold text-danger">
    Delivery Charge: {deliveryCharge === 0 ? "FREE" : `₹${deliveryCharge}`}
  </td>
  
  <td colSpan="5" className="text-end fw-bold text-danger">
    Handling Charge: {handlingCharge === 0 ? "FREE" : `₹${handlingCharge}`}
  </td>      
</tr>
{cashbackAmount > 0 && (
<tr>
  <td colSpan="9" className="text-end fw-bold text-success">
    Cashback Earned:
  </td>
  <td className="fw-bold text-success">
    ₹{cashbackAmount}
  </td>
</tr>
)}
    <tr>
      <td colSpan="9" className="text-end fw-bold">
        Grand Total:
      </td>
      <td className="fw-bold">     
        ₹{grandTotal}
      </td>
    </tr> 
 <tr>
      <td colSpan="9" className=" text-danger text-end fw-bold">
        Your's current wallet balance :
      </td>
      <td className="fw-bold">     
        ₹{remainingAmount}
      </td>  
      </tr>
  </tfoot>  
</table>
<div className="text-end">
  <button
          style={{
            background: "red",
            color: "white",
            borderRadius: "20px",
            padding: "8px",
          }}
          onClick={handleDownloadPDF}
        >
          Download PDF
        </button>
</div>

        {/* <div className='payment'>
        <label className='fw-bold fs-5 w-100 p-2' style={{ background: "green", color: "white", borderRadius: "15px", width: "25px" }}>Payment Mode</label>
        <label className='fs-5 '>
            <input 
            type="radio" 
            className="form-check-input border-secondary m-2 border-dark"
            checked={paymentMode === 'online'}
            readOnly
             />
            Pay Through Online
          </label>
          <label className='fs-5'>
            <input 
            type="radio" 
            className="form-check-input border-secondary border-dark m-2"
            checked={paymentMode === 'cash'}
            readOnly
            />
            Cash On Delivery
          </label>
    </div>  */}

    {/* <div className="form-group mt-0">
              <label>Payment Transaction Details </label>
              <input
                type="text"
                className="form-control "
                value={transactionDetails}
                onChange={(e) => setTransactionDetails(e.target.value)}
                placeholder="Payment Transaction Details"
                readOnly
              />
            </div> */}
            <Row>
                  {/* Assigned To
                  <Col md={12}>
                    <Form.Group>
                      <label>Assigned To</label>
                      <Form.Control as="select" value={assignedTo} onChange={handleAssignedToChange} required>
                        <option value="">Select Assigned</option>
                        <option value="Delivery Partner">Delivery Partner</option>
                      </Form.Control>
                      {error.assignedTo && <p className="text-danger">{error.assignedTo}</p>}
                    </Form.Group>
                  </Col> */}

                   {/* New Delivery Partner Names Dropdown */}
                  <Col md={12}>
                    <Form.Group>
                      <label>Delivery Partner Names</label>
                      <Form.Control
                        as="select"
                        value={selectedPartner}
                        onChange={(e) => setSelectedPartner(e.target.value)}
                        required
                      >
                        <option value="">Select Delivery Partner</option>
                        {deliveryPartners.map((partner) => (
                          <option key={partner.id} value={partner.deliveryPartnerId}>
                            {partner.deliveryPartnerName}
                          </option>
                        ))}
                      </Form.Control>
                    </Form.Group>
                  </Col>
                </Row> 
            <div className="mt-2 d-flex justify-content-between">
            <Button type="submit" className=" text-white mx-2" style={{background: 'green'}} onClick={() => navigate(`/adminGroceryZoneDashboard`)} title="Back">
                <ArrowBack />
                </Button>
                <Button
                  type="submit"
                  className="text-white mx-2"
                  style={{ background: 'green' }}
                  title="Forward"
                  onClick={handleUpdatePaymentMethod}
                 disabled={!!paidAmount || !selectedPartner}
                >
                  <ForwardIcon />
                </Button>
                <Button
                  className="text-white mx-2"
                  style={{ background: "red" }}
                  onClick={handleCancelOrder}
                  title="Cancel Order"
                  disabled={selectedPartner}
                >
                  Cancel
                </Button>
            </div>
          </form>
        </div>
      </div>
       <Modal
              show={showZoomModal}
              onHide={() => {
                setShowZoomModal(false);
                setZoomProduct(null);
              }}
              centered
            >
              <button
                className="close-button text-end mt-0"
                onClick={() => {
                  setShowZoomModal(false);
                  setZoomProduct(null);
                }}
              >
                &times;
              </button>
              <Modal.Body className="text-center">
                <div className="zoom-container">
                  <img
                    src={zoomImage}
                    alt={zoomProduct?.name || "Zoomed Product"}
                    className="zoom-image"
                  />
                </div>
                <h6
                className="text-start fw-bold m-0"
                style={{ fontSize: "20px" }}
              >
                {zoomProduct?.name || ""}
              </h6>
              </Modal.Body>
            </Modal>
      {/* Styles for floating menu */}
<style jsx>{`
        .floating-menu {
          position: fixed;
          top: 80px; /* Increased from 20px to avoid overlapping with the logo */
          left: 20px; /* Adjusted for placement on the left side */
          z-index: 1000;
        }
        .menu-popup {
          position: absolute;
          top: 50px; /* Keeps the popup aligned below the floating menu */
          left: 0; /* Aligns the popup to the left */
          background: white;
          border: 1px solid #ddd;
          border-radius: 5px;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
          width: 200px;
        }
      `}</style>    
    </div>
    <Footer /> 
    </>
  );
};
 
export default AdminGroceryOrderPage;
